package net.civeira.phylax.features.oauth.par.domain.gateway;

/**
 * Binds a consumed pushed request to the browser that consumed it (task 0.14).
 *
 * <p>
 * A {@code request_uri} is spent by the first authorization request; the login forms that follow
 * post to the same URL, so the browser keeps a binding (a cookie) that only the server can produce
 * for that {@code request_uri}. Another browser replaying the URI has no binding and is rejected.
 */
public interface ParBindingGateway {

  /**
   * Binding of a request URI.
   *
   * @param requestUri consumed pushed request
   * @return value for the browser
   */
  String bind(String requestUri);

  /**
   * Whether a browser binding belongs to a request URI.
   *
   * @param requestUri pushed request
   * @param binding value presented by the browser
   * @return true when it was produced by {@link #bind(String)} for that URI
   */
  boolean verify(String requestUri, String binding);
}
